"use strict";const btnCreateAccount=document.querySelector(".btn-create-account");btnCreateAccount&&btnCreateAccount.addEventListener("click",()=>{showToast("Création de compte en cours...","info"),setTimeout(()=>{showToast("Fonctionnalité à venir : Formulaire de création de compte","info")},1500)});const approveButtons=document.querySelectorAll(".action-approve"),rejectButtons=document.querySelectorAll(".action-reject");approveButtons.forEach(t=>{t.addEventListener("click",e=>{e.preventDefault();const o=t.getAttribute("aria-label")||"Compte";showToast(`${o} approuvé`,"success")})}),rejectButtons.forEach(t=>{t.addEventListener("click",e=>{e.preventDefault();const o=t.getAttribute("aria-label")||"Compte";showToast(`${o} rejeté`,"warning")})});